 3	public final class LongestCommonSubsequence {
 4	    private static final String SAMPLE_FIRST = "AGGTAB";
 5	    private static final String SAMPLE_SECOND = "GXTXAYB";
 6	
 7	    private LongestCommonSubsequence() {
 8	    }
