10	    public static int lcs(String first, String second) {
11	        Objects.requireNonNull(first, "first must not be null");
12	        Objects.requireNonNull(second, "second must not be null");
13	
14	        if (first.isEmpty() || second.isEmpty()) {
15	            return 0;
16	        }
17	
18	        if (first.equals(second)) {
19	            return first.length();
20	        }
21	
22	        return computeLcsLength(normalizeByLength(first, second));
23	    }
24	
25	    private static int computeLcsLength(NormalizedSequences sequences) {
26	        char[] longer = sequences.longer();
27	        char[] shorter = sequences.shorter();
28	        int[] lengths = new int[shorter.length + 1];
29	
30	        for (char current : longer) {
31	            int diagonal = 0;
32	
33	            for (int j = 1; j <= shorter.length; j++) {
34	                int previousRow = lengths[j];
35	
36	                lengths[j] = current == shorter[j - 1]
37	                    ? diagonal + 1
38	                    : Math.max(lengths[j], lengths[j - 1]);
39	                diagonal = previousRow;
40	            }
41	        }
42	
43	        return lengths[shorter.length];
44	    }
45	
46	    private static NormalizedSequences normalizeByLength(String first, String second) {
47	        char[] firstChars = first.toCharArray();
48	        char[] secondChars = second.toCharArray();
49	
50	        if (firstChars.length >= secondChars.length) {
51	            return new NormalizedSequences(firstChars, secondChars);
52	        }
53	
54	        return new NormalizedSequences(secondChars, firstChars);
55	    }
56	
